import {drawImpacts} from './impact.mjs';
import {WORLD,point,terrain} from './physics.mjs';
import {drawEnvironment} from './environment.mjs';
import {drawCrowd} from './people.mjs';
function path(c,points,fill,stroke){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.stroke();}}
function round(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.stroke();}}
function text(c,t,x,y,size,color,align='center',weight=700){c.font=`${weight} ${size}px Arial, sans-serif`;c.textAlign=align;c.fillStyle=color;c.fillText(t,x,y);}
function wheel(c,x,y,r,angle){c.save();c.translate(x,y);c.fillStyle='#080f1a';c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.strokeStyle='#263141';c.lineWidth=2;c.stroke();c.fillStyle='#8793a3';c.beginPath();c.arc(0,0,r*.69,0,Math.PI*2);c.fill();c.rotate(angle);for(let i=0;i<5;i++){c.rotate(Math.PI*2/5);c.fillStyle='#263443';c.beginPath();c.ellipse(0,-r*.43,2.4,3.5,0,0,Math.PI*2);c.fill();}c.fillStyle='#c4cbd5';c.beginPath();c.arc(0,0,2.6,0,Math.PI*2);c.fill();c.restore();}
export function car(c,s){
 c.save();c.translate(s.x,s.y);c.rotate(s.a);c.translate(0,s.lastImpact*Math.sin(s.lastImpact*12)*2);c.lineWidth=.8;
 const body=c.createLinearGradient(0,-28,0,17);body.addColorStop(0,'#fffef7');body.addColorStop(.38,'#eff4f5');body.addColorStop(.7,'#d8e1e9');body.addColorStop(1,'#8c9dac');
 // Low teardrop cabin, flowing rear haunch and a long, pointed nose.
 c.beginPath();c.moveTo(-75,1);c.lineTo(-73,-10);c.quadraticCurveTo(-63,-15,-48,-14);c.lineTo(-31,-20);c.quadraticCurveTo(-19,-27,-8,-27);c.lineTo(6,-26);c.quadraticCurveTo(21,-22,35,-12);c.quadraticCurveTo(60,-10,73,-4);c.lineTo(77,2);c.lineTo(72,11);c.quadraticCurveTo(2,19,-70,12);c.closePath();c.fillStyle=body;c.fill();c.strokeStyle='#b8cad8';c.stroke();
 // Single dark canopy and raked windscreen: no upright sedan pillars.
 c.beginPath();c.moveTo(-35,-16);c.lineTo(-26,-20);c.quadraticCurveTo(-14,-25,-5,-25);c.lineTo(5,-24);c.quadraticCurveTo(17,-21,29,-13);c.lineTo(-35,-16);c.fillStyle='#0b1a29';c.fill();
 path(c,[[6,-24],[29,-13],[18,-14],[-2,-24]],'#233f54');
 c.strokeStyle='#b7d6e4';c.lineWidth=.7;c.beginPath();c.moveTo(-27,-20);c.quadraticCurveTo(-11,-26,5,-24);c.lineTo(28,-13);c.stroke();
 // Sculpted shoulder, recessed door and a carbon sill.
 c.beginPath();c.moveTo(-70,-9);c.quadraticCurveTo(-48,-12,-29,-10);c.quadraticCurveTo(7,-5,36,-10);c.quadraticCurveTo(57,-9,70,-5);c.strokeStyle='#ffffff';c.lineWidth=1.3;c.stroke();
 path(c,[[-30,-12],[23,-11],[18,7],[-28,10]],'#eaf0f3','#a9bbc9');
 path(c,[[-30,9],[19,5],[30,9],[-30,14]],'#b2c1ce');
 path(c,[[-65,13],[63,12],[68,17],[-64,18]],'#1c2e3f');
 c.fillStyle='#718697';c.fillRect(13,-8,7,1.5);
 // Small mirrors, thin lamps and a low front intake.
 path(c,[[19,-15],[25,-17],[29,-14],[25,-12]],'#c6d9e3','#6e869a');
 path(c,[[60,-6],[72,-3],[70,-.5],[59,-3]],'#edffff','#b7e1ee');
 path(c,[[64,6],[75,4],[71,10],[61,10]],'#122231');
 path(c,[[-74,-7],[-64,-7],[-64,-4],[-73,-4]],'#fa7265');
 c.fillStyle='#152637';c.fillRect(-73,6,8,3);
 for(const x of [-49,49]){c.fillStyle='#0b1522';c.beginPath();c.arc(x,14,17,Math.PI,0);c.fill();c.beginPath();c.arc(x,14,17,Math.PI+.1,Math.PI*2-.1);c.strokeStyle='#b9cbd7';c.lineWidth=1.3;c.stroke();if(!s.detachedWheels)wheel(c,x,14,14,s.wheel);}
 c.fillStyle='#405a70';c.fillRect(-52,26,7,4);c.fillRect(45,26,7,4);c.restore();
}
function van(c){const {x,y,w}=WORLD.van;c.save();c.translate(x,y);let g=c.createLinearGradient(0,0,0,115);g.addColorStop(0,'#ee8b29');g.addColorStop(.4,'#c85a0e');g.addColorStop(1,'#87380c');path(c,[[0,15],[9,0],[171,0],[195,10],[216,43],[239,56],[244,108],[0,108]],g,'#ffad4b');round(c,9,12,140,79,6,null,'#a9470b');path(c,[[170,12],[189,20],[207,48],[171,48]],'#0a2032','#c97a3a');c.strokeStyle='#9a3d0c';c.beginPath();c.moveTo(163,7);c.lineTo(163,100);c.stroke();c.fillStyle='#813707';c.fillRect(151,59,9,4);round(c,-3,97,250,13,3,'#132234');c.fillStyle='#ff695b';c.fillRect(-2,59,6,18);c.fillStyle='#fff0ba';c.fillRect(232,59,9,16);wheel(c,45,110,20,0);wheel(c,201,110,20,0);c.restore();}
function ramp(c){const {rampStart:a,rampEnd:b,ground:g}=WORLD;c.beginPath();c.moveTo(a,g);for(let x=a;x<=b;x+=3)c.lineTo(x,terrain(x).y);c.lineTo(b,g);c.closePath();c.fillStyle='#29333c';c.fill();for(let x=a+40;x<b;x+=55){const top=terrain(x).y;path(c,[[x,top+7],[x+16,top+4],[x-9,g],[x-25,g]],'#0d1826');}c.beginPath();c.moveTo(a,g);for(let x=a;x<=b;x+=2)c.lineTo(x,terrain(x).y);c.strokeStyle='#c2ac87';c.lineWidth=6;c.stroke();c.strokeStyle='#f0cc8d';c.lineWidth=2;c.stroke();c.fillStyle='#f8cd7b';c.shadowColor='#ffba54';c.shadowBlur=14;c.fillRect(a+35,g-6,6,6);c.fillRect(b-9,terrain(b).y-6,6,6);c.shadowBlur=0;}
function parking(c,time,landed){let a=WORLD.padStart,b=WORLD.padEnd,g=WORLD.ground;const glow=c.createLinearGradient(0,g-30,0,g+20);glow.addColorStop(0,'#88ffd000');glow.addColorStop(1,'#8dffd020');c.fillStyle=glow;c.fillRect(a-25,g-40,b-a+50,63);c.strokeStyle='#93ffdb';c.shadowColor='#80ffd1';c.shadowBlur=landed?24:11;c.lineWidth=4;path(c,[[a,g+7],[a+23,g-10],[b-23,g-10],[b,g+7]],null,'#93ffdb');c.beginPath();c.moveTo(a,g+7);c.lineTo(b,g+7);c.stroke();c.shadowBlur=0;path(c,[[a-30,g],[a-30,g-18],[a-17,g-23],[a-9,g-17],[a-9,g]],'#88918a');path(c,[[b+10,g],[b+10,g-18],[b+24,g-22],[b+30,g-15],[b+30,g]],'#88918a');c.fillStyle='#64777d';c.fillRect(b+53,g-133,5,133);round(c,b+33,g-178,46,49,4,'#164882','#d9f1fb');text(c,'P',b+56,g-141,35,'#fff');c.fillStyle='#4b6065';c.fillRect(b+88,g-66,5,66);round(c,b+76,g-103,28,46,5,'#182b32','#768e8a');round(c,b+80,g-97,20,13,2,landed?'#9fffd7':'#9ac9bd');text(c,landed?'NICELY PARKED':'STICK THE LANDING',(a+b)/2,g-55,13,'#9af7d5');let bob=Math.sin(time*3)*3;path(c,[[(a+b)/2-6,g-40+bob],[(a+b)/2+6,g-40+bob],[(a+b)/2,g-32+bob]],'#9af7d5');}
export function drawWorld(c,s,{background=null,impacts=[],particles=[],time=0,reduced=false,camera={x:0,y:0,zoom:1},width=1600,height=900,backdrop=null,people={},spectator=null}={}){c.clearRect(0,0,width,height);drawEnvironment(c,{background,camera,width,height,time});if(backdrop)backdrop();c.save();c.scale(camera.zoom,camera.zoom);c.translate(-camera.x,-camera.y);drawCrowd(c,people,time,reduced,spectator);c.fillStyle='#0005';c.beginPath();c.ellipse(s.x,WORLD.ground+7,Math.max(30,75-(WORLD.ground-s.y)*.05),6,0,0,7);c.fill();ramp(c);van(c);parking(c,time,s.phase==='landed');for(const p of particles){let k=p.life/p.max;c.globalAlpha=k*p.alpha;let radius=p.r+(1-k)*p.expand;let fog=c.createRadialGradient(p.x,p.y,0,p.x,p.y,radius);fog.addColorStop(0,p.color);fog.addColorStop(.5,p.color+'99');fog.addColorStop(1,p.color+'00');c.fillStyle=fog;c.fillRect(p.x-radius,p.y-radius,radius*2,radius*2);}c.globalAlpha=1;
for(const [x,on] of [[-49,s.rear],[49,s.front]])if(on){c.save();const p=point(s,x,29);c.translate(p.x,p.y);c.rotate(s.a);let len=(reduced?100:100+Math.sin(time*53+x)*16)*on;let grad=c.createLinearGradient(0,0,0,len);grad.addColorStop(0,'#f5ffffee');grad.addColorStop(.2,'#d1f5ffbb');grad.addColorStop(1,'#b4e1ff00');c.fillStyle=grad;c.beginPath();c.moveTo(-2,0);c.lineTo(-15,len);c.quadraticCurveTo(0,len+13,15,len);c.lineTo(2,0);c.closePath();c.fill();c.shadowColor='#b8ecff';c.shadowBlur=12;c.fillStyle='#fff';c.fillRect(-2,0,4,11);c.restore();}
equipment(c,s,time);car(c,s);drawImpacts(c,impacts,time);c.restore();}

function equipment(c,s,time){
 if(s.gear==='rocket'){c.save();c.translate(s.x,s.y);c.rotate(s.a);round(c,-11,13,22,10,3,'#556579','#9cb5ce');path(c,[[-8,20],[8,20],[14,28],[-14,28]],'#263a50','#9cb5ce');if(s.rocket){let len=190+Math.sin(time*64)*20;let fire=c.createLinearGradient(0,27,0,27+len);fire.addColorStop(0,'#fffaf4');fire.addColorStop(.16,'#96eaff');fire.addColorStop(.55,'#ffb250cc');fire.addColorStop(1,'#ff673300');c.fillStyle=fire;c.shadowBlur=20;c.shadowColor='#ff9d41';c.beginPath();c.moveTo(-11,27);c.bezierCurveTo(-22,95,-7,160,0,27+len);c.bezierCurveTo(8,170,21,90,11,27);c.closePath();c.fill();c.shadowBlur=0;c.fillStyle='#efffff';path(c,[[-5,27],[5,27],[0,100]],'#efffff');}c.restore();}
 if(s.gear==='parachute'&&!s.parachute&&!s.chuteUsed){let p=point(s,-37,-19);round(c,p.x-12,p.y-6,24,12,4,'#ea9e48','#ffd294');}
 if(s.parachute){let k=s.chuteOpen,cx=s.x-s.vx*.08+Math.sin(time*2)*4,cy=s.y-165*k,r=122*k;c.save();c.strokeStyle='#e6e7d8bb';c.lineWidth=1.5;for(const side of [-1,1]){let anchor=point(s,side*37,-18);for(let n=-1;n<=1;n+=1){c.beginPath();c.moveTo(anchor.x,anchor.y);c.lineTo(cx+(side*.65+n*.22)*r,cy+20*k);c.stroke();}}
 c.beginPath();c.moveTo(cx-r,cy+20*k);c.bezierCurveTo(cx-r,cy-95*k,cx+r,cy-95*k,cx+r,cy+20*k);for(let j=3;j>=0;j--){let x=cx-r+j*r*.5;c.quadraticCurveTo(x+r*.25,cy-2*k,x,cy+20*k);}c.closePath();let cloth=c.createLinearGradient(0,cy-65*k,0,cy+22*k);cloth.addColorStop(0,'#ffe2a6');cloth.addColorStop(.45,'#ffae52');cloth.addColorStop(1,'#df7130');c.fillStyle=cloth;c.fill();c.strokeStyle='#ffe5b6';c.lineWidth=2;c.stroke();c.beginPath();c.moveTo(cx-r*.5,cy+20*k);c.quadraticCurveTo(cx-r*.4,cy-85*k,cx,cy-65*k);c.quadraticCurveTo(cx+r*.4,cy-85*k,cx+r*.5,cy+20*k);c.strokeStyle='#ffefcc99';c.stroke();c.restore();}
}
